SELECT *
FROM t_async_task
WHERE status    = #{runningCode}
  AND timeout_at  <  #{now}
  AND deleted    = 0
ORDER BY timeout_at ASC
LIMIT #{limit}

SELECT *
FROM t_async_task
WHERE status    = #{submittedCode}
  AND created_at  <  #{before}
  AND deleted    = 0
ORDER BY created_at ASC
LIMIT #{limit}

SELECT COUNT(*)
FROM t_async_task
WHERE task_type = #{taskType}
  AND biz_id    = #{bizId}
  AND status   IN

      #{code}

  AND deleted   = 0
